/// <summary>
/// The <c>AVAWHSProcessGuidePromptChangePrinterStep</c> class represents the step for changing the printer
/// details and confirming the same.
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePromptChangePrinterStep))
]
class AVAWHSProcessGuidePromptChangePrinterStep extends ProcessGuideStep
{
}

Method.Source:
protected final boolean isComplete() 
{ 
    boolean             ret; 
    WhsrfPassthrough    pass = controller.parmSessionState().parmPass();

    if (pass.lookupStr(ProcessGuideDataTypeNames::AVAPrinterCode))
    { 
        ret = true;
    } 

    return ret;
}
